import{_ as a,c as e,o as t,a4 as r}from"./chunks/framework.D5y910bP.js";const x=JSON.parse('{"title":"xatlas.js and xatlas-three","description":"","frontmatter":{"date":"2020-11-12T00:00:00.000Z","tags":["javascript","xatlas","three.js","mesh","parameterization","uv","unwrap"],"title":"xatlas.js and xatlas-three"},"headers":[],"relativePath":"blog/xatlas-js.md","filePath":"blog/xatlas-js.md","lastUpdated":1754760041000}'),s={name:"blog/xatlas-js.md"},l=r('<h1 id="xatlas-js-and-xatlas-three" tabindex="-1">xatlas.js and xatlas-three <a class="header-anchor" href="#xatlas-js-and-xatlas-three" aria-label="Permalink to &quot;xatlas.js and xatlas-three&quot;">​</a></h1><h2 id="xatlas-js-xatlas-wrapper" tabindex="-1"><strong>xatlas.js</strong> - (xAtlas Wrapper) <a class="header-anchor" href="#xatlas-js-xatlas-wrapper" aria-label="Permalink to &quot;**xatlas.js** - (xAtlas Wrapper)&quot;">​</a></h2><p>Mesh parameterization library for use on web and js.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>xatlas.js is a wrapper for xatlas for js. It uses <code>emcc</code> to compile WASM from C++ codebase and can be used as a simple js module or as a webworker with <a href="https://github.com/GoogleChromeLabs/comlink" target="_blank" rel="noreferrer">comlink</a></p><p><a href="https://github.com/jpcy/xatlas" target="_blank" rel="noreferrer">xatlas</a> is a small C++11 library with no external dependencies that generates unique texture coordinates suitable for baking lightmaps or texture painting. It is an independent fork of <a href="https://github.com/Thekla/thekla_atlas" target="_blank" rel="noreferrer">thekla_atlas</a>, used by <a href="https://en.wikipedia.org/wiki/The_Witness_(2016_video_game)" target="_blank" rel="noreferrer">The Witness</a>.</p></div><p>Github: <a href="https://github.com/repalash/xatlas.js" target="_blank" rel="noreferrer">https://github.com/repalash/xatlas.js</a></p><h2 id="xatlas-three-xatlas-three-js" tabindex="-1"><strong>xatlas-three</strong> - XAtlas + Three.js <a class="header-anchor" href="#xatlas-three-xatlas-three-js" aria-label="Permalink to &quot;**xatlas-three** - XAtlas + Three.js&quot;">​</a></h2><p>Mesh parameterization / UV unwrapping module for three.js</p><p>Github: <a href="https://github.com/repalash/xatlas-three" target="_blank" rel="noreferrer">https://github.com/repalash/xatlas-three</a></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="https://github.com/jpcy/xatlas" target="_blank" rel="noreferrer">xAtlas</a> + <a href="https://github.com/mrdoob/three.js" target="_blank" rel="noreferrer">three.js</a>: Mesh parameterization / UV unwrapping module for three.js in wasm with webworkers.</p><p>Can be used to unwrap UVs in <code>BufferGeometry</code> or pack multiple geometries into a single atlas for lightmap/AO baking.</p><p>To use xatlas in JS without three.js you can use <a href="https://github.com/repalash/xatlas.js" target="_blank" rel="noreferrer">xatlas.js</a> directly.</p></div><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><ul><li>Unwrap geometry and debug UV - <a href="https://repalash.com/xatlas-three/public/uvs-debug.html" target="_blank" rel="noreferrer">https://repalash.com/xatlas-three/public/uvs-debug.html</a></li><li>Pack multiple geometries into a single atlas and unwrap GLTF - <a href="https://repalash.com/xatlas-three/public/pack-atlas.html" target="_blank" rel="noreferrer">https://repalash.com/xatlas-three/public/pack-atlas.html</a></li></ul>',11),o=[l];function h(i,n,p,c,m,u){return t(),e("div",null,o)}const b=a(s,[["render",h]]);export{x as __pageData,b as default};
